static xcronselectedservicestats ssReady(ssfixture* F,uint32 Ready,uint32 Unsent)
{double End=xrtTimer()+10;for(;;){xcronselectedservicestats T=ssStats(F->Service);if(T.Service.ReadyCompletions==Ready && T.Service.Unsent==Unsent)return T;testRequire(T.Service.State!=XCRON_SERVICE_FAILED && xrtTimer()<End,"selected output/retry progress");xrtThreadYield();}}
static void testSSMissingAndWindows(void)
{
    for(unsigned Missing=0;Missing<2;++Missing){xcronzone* Z=NULL;testRequire(xcronZoneCreatePosix(XRT_STR_LITERAL("EST5EDT,M3.2.0,M11.1.0"),XCRON_ZONE_TZIF3,&Z,NULL),"selected missing-label zone");xtime Begin,End,Nominal,Anchor;testRequire(xrtDateTime(2024,3,10,6,0,0,0,&Begin) && xrtDateTime(2024,3,10,8,0,0,0,&End) && xrtDateTime(2024,3,10,2,30,0,0,&Nominal) && xrtDateTime(2024,3,10,7,0,0,0,&Anchor),"selected gap anchors");xdatetime Local;xrtTimeSplit(Nominal,&Local);Local.Offset=0;Local.IsDST=-1;
        ssfixture F=ssFixture(End,&Local,0);xexecutor* E=ssPool(1,8);xcronselectedserviceconfig C=ssConfig(E,&F);C.Service.Scheduler.WorkLimit=1;ssStart(&F,&C);xcronjobconfig J=ssJob(Z,&F,Begin,End);testRequire(xcronExpressionCompile(XRT_STR_LITERAL("0 30 2 * * *"),XCRON_SECONDS6,&J.Expression,NULL),"missing matching label");xcronjobid Job=ssAdd(&F,&J,(xcrondeliverypolicy){XCRON_FOLD_ALL,(xcronmissingpolicy)Missing});xcronZoneRelease(Z);
        double Deadline=xrtTimer()+10;xcronselectedjobinfo Info;do{Info=ssInfo(F.Service,Job);testRequire(xrtTimer()<Deadline,"missing policy job reaches terminal state");}while(Info.State==XCRON_JOB_SEARCHING);
        testRequire(Info.State==(Missing?XCRON_JOB_FAULTED:XCRON_JOB_EXHAUSTED) && !Info.Dispatched && !xrtAtomic64Load(&F.Calls,XMEMORY_ACQUIRE),"missing skip/reject has no accidental physical callback");
        if(Missing)testRequire(Info.LastIssue.Code==XCRON_OCCURRENCE_MISSING && Info.LastIssue.When==Anchor && !Info.LastIssue.Candidates && !memcmp(&Info.LastIssue.Local,&Local,sizeof(Local)),"complete selected missing fault survives service Info");
        testRequire(ssStats(F.Service).Service.Failure.Code==XCRON_SERVICE_OK,"per-job missing fault does not fail the owner");ssStop(&F);xcronselectedretired R;bool Found;testRequire(xcronServiceReapStoppedSelected(F.Service,&R,&Found,NULL) && Found && R.Id==Job && R.Info.Policy.Missing==(xcronmissingpolicy)Missing && (!Missing || R.Info.LastIssue.Code==XCRON_OCCURRENCE_MISSING),"complete missing metadata survives retirement");ssClear(&F);ssPoolEnd(E);
    }
    for(unsigned Last=0;Last<2;++Last){xcronzone* Z=NULL;xtime At[2];xdatetime Local;ssFoldFixture(&Z,At,&Local);ssfixture F=ssFixture(At[1],&Local,2);xexecutor* E=ssPool(1,8);xcronselectedserviceconfig C=ssConfig(E,&F);ssStart(&F,&C);xtime Only=At[Last?0:1];xcronjobconfig J=ssJob(Z,&F,Only,Only);xcronjobid Job=ssAdd(&F,&J,(xcrondeliverypolicy){Last?XCRON_FOLD_LAST:XCRON_FOLD_FIRST,XCRON_MISSING_REJECT});xcronZoneRelease(Z);
        double Deadline=xrtTimer()+10;xcronselectedjobinfo Info;do{Info=ssInfo(F.Service,Job);testRequire(xrtTimer()<Deadline,"global candidate outside service window excluded");}while(Info.State==XCRON_JOB_SEARCHING);testRequire(Info.State==XCRON_JOB_EXHAUSTED && !Info.Dispatched && !xrtAtomic64Load(&F.Calls,XMEMORY_ACQUIRE),"service uses global first/last rather than window-local candidates");ssStop(&F);ssClear(&F);ssPoolEnd(E);
    }
}
typedef struct ssblocker {xatomic32 Started,Gate;} ssblocker;
static void ssBlock(ptr Raw)
{ssblocker* B=Raw;xrtAtomic32Store(&B->Started,1,XMEMORY_RELEASE);double End=xrtTimer()+10;while(!xrtAtomic32Load(&B->Gate,XMEMORY_ACQUIRE)){testRequire(xrtTimer()<End,"external selected service pool gate");xrtThreadYield();}}
static void testSSRetryMetadata(void)
{
    for(unsigned Cancel=0;Cancel<2;++Cancel){xcronzone* Z=NULL;xtime At[2];xdatetime Local;ssFoldFixture(&Z,At,&Local);ssfixture F=ssFixture(At[1],&Local,2);xexecutor* E=ssPool(1,1);ssblocker Block={0};testRequire(xrtExecutorSubmit(E,ssBlock,&Block,NULL,NULL),"external native blocker");ssUntil(&Block.Started,1,"native selected pool blocked");testRequire(xrtExecutorSubmit(E,ssBlock,&Block,NULL,NULL),"external native queue full");
        xcronselectedserviceconfig C=ssConfig(E,&F);ssStart(&F,&C);xcronjobconfig J=ssJob(Z,&F,At[0],At[1]);xcronjobid Job=ssAdd(&F,&J,(xcrondeliverypolicy){XCRON_FOLD_ALL,XCRON_MISSING_REJECT});xcronZoneRelease(Z);xcronselectedservicestats T=ssReady(&F,0,2);testRequire(T.BatchSubmissions==1 && T.BatchedAttempts==2 && T.Service.SubmitAttempts==2 && T.Service.RejectedSubmissions==2 && !T.Service.Executor.Active && !xrtAtomic64Load(&F.Calls,XMEMORY_ACQUIRE),"atomic batch rejection is counted per lease and retains both retry duties");
        if(Cancel){xcronrequestid Q;testRequire(xcronServiceCancelAsync(F.Service,Job,true,&Q,NULL),"cancel selected unsent job");xcronselectedreply R=ssReply(F.Service,Q);testRequire(R.Code==XCRON_SERVICE_OK && !R.Error,"selected job cancellation reply");}
        else {xrtAtomic64Store(&F.Mono,110,XMEMORY_RELEASE);testRequire(xcronServiceWake(F.Service,NULL),"advance selected retry deadline");double Deadline=xrtTimer()+10;
            do{T=ssStats(F.Service);testRequire(xrtTimer()<Deadline,"two individual retry attempts observed");xrtThreadYield();}while(T.Service.Retries<2);
            testRequire(T.Service.SubmitAttempts==4 && T.Service.RejectedSubmissions==4 && T.Service.Unsent==2,"batch retries are individual and retain original deadlines");xrtAtomic64Store(&F.Mono,200,XMEMORY_RELEASE);testRequire(xcronServiceWake(F.Service,NULL),"expire original selected admission window");}
        unsigned Seen=0;for(unsigned N=0;N<2;++N){xcronselectedservicecompletion D=ssDone(F.Service);unsigned Index=D.Completion.ScheduledAt==At[0]?0:1;testRequire(D.Completion.ScheduledAt==At[Index] && !(Seen&(1u<<Index)) && D.Completion.Job==Job && D.Candidates==2 && !memcmp(&D.Local,&Local,sizeof(Local)),"unsent metadata survives active union through retries and Finish");Seen|=1u<<Index;
            testRequire(D.Completion.Result==(Cancel?XCRON_RUN_CANCELLED:XCRON_RUN_FAILED) && D.Completion.Code==(Cancel?XCRON_COMPLETION_CANCELLED:XCRON_COMPLETION_EXPIRED) && D.Completion.Attempts==(Cancel?1u:2u),"per-lease cancelled/expired attempt result");if(Cancel)testRequire(!D.Completion.Error,"cancel releases prior rejection error");else testRequire(D.Completion.Error!=NULL,"expiry transfers last owned rejection diagnostic");xrtErrorFree(D.Completion.Error);}
        testRequire(Seen==3 && !xrtAtomic64Load(&F.Calls,XMEMORY_ACQUIRE),"no rejected operation was replayed as business work");ssStop(&F);ssClear(&F);xrtAtomic32Store(&Block.Gate,1,XMEMORY_RELEASE);ssPoolEnd(E);
    }
    for(unsigned Mode=0;Mode<3;++Mode){xcronzone* Z=NULL;xtime At[2];xdatetime Local;ssFoldFixture(&Z,At,&Local);ssfixture F=ssFixture(At[1],&Local,2);F.Mode=Mode?Mode:0;xexecutor* E=ssPool(2,8);xcronselectedserviceconfig C=ssConfig(E,&F);ssStart(&F,&C);xcronjobconfig J=ssJob(Z,&F,At[0],At[1]);ssAdd(&F,&J,(xcrondeliverypolicy){0,1});xcronZoneRelease(Z);
        for(unsigned N=0;N<2;++N){xcronselectedservicecompletion D=ssDone(F.Service);testRequire(D.Candidates==2 && !memcmp(&D.Local,&Local,sizeof(Local)) && D.Completion.Result==(Mode?XCRON_RUN_FAILED:XCRON_RUN_SUCCEEDED) && D.Completion.Executor==(Mode==2?XCRON_EXECUTOR_RESULT:XCRON_EXECUTOR_OK),"selected service independent batch worker outcomes");if(Mode==1)testRequire(D.Completion.Error && xrtErrorCode(D.Completion.Error)==29 && !strcmp(xrtErrorDomain(D.Completion.Error),"selected.service.body"),"worker error ownership transferred independently");else testRequire(!D.Completion.Error,"no stale selected batch business error");xrtErrorFree(D.Completion.Error);}
        ssStop(&F);ssClear(&F);ssPoolEnd(E);
    }
}
static xcronrunresult ssHeapProc(const xcronrun* R,const xcronexecution* T,ptr Raw)
{
    ssfixture* F=Raw;const xcronexecutionlabel* L=xcronExecutionSelected(T);testRequire(R->Data && *(const int*)R->Data==42 && L && L->Candidates==2 && !memcmp(&L->Local,&F->Local,sizeof(F->Local)),"heap Data and nominal view reach selected worker");xrtAtomic32FetchAdd(&F->Started,1,XMEMORY_RELEASE);double End=xrtTimer()+10;
    while(!xrtAtomic32Load(&F->Gate,XMEMORY_ACQUIRE)){testRequire(*(const int*)R->Data==42 && xrtTimer()<End,"data-using tail retains heap Data after cancellation");xrtThreadYield();}
    return xcronExecutionCancelled(T)?XCRON_RUN_CANCELLED:XCRON_RUN_SUCCEEDED;
}
static void testSSPhysicalAndCredits(void)
{
    xcronzone* Z=NULL;xtime At[2];xdatetime Local;ssFoldFixture(&Z,At,&Local);ssfixture F=ssFixture(At[1],&Local,2);xrtAtomic32Store(&F.Gate,0,XMEMORY_RELAXED);xexecutor* E=ssPool(2,8);xcronselectedserviceconfig C=ssConfig(E,&F);C.Service.Proc=ssHeapProc;ssStart(&F,&C);int* Data=xrtMalloc(sizeof(*Data));testRequire(Data!=NULL,"selected heap business data");*Data=42;xcronjobconfig J=ssJob(Z,&F,At[0],At[1]);J.Data=Data;xcronjobid Job=ssAdd(&F,&J,(xcrondeliverypolicy){0,1});xcronZoneRelease(Z);ssUntil(&F.Started,2,"both selected physical bodies entered");
    xcronrequestid Q;testRequire(xcronServiceCancelAsync(F.Service,Job,true,&Q,NULL),"cancel selected physical job");xcronselectedreply Reply=ssReply(F.Service,Q);testRequire(Reply.Code==XCRON_SERVICE_OK && !Reply.Error && xcronServiceReapAsync(F.Service,&Q,NULL),"selected async retirement while tails run");Reply=ssReply(F.Service,Q);testRequire(Reply.Code==XCRON_SERVICE_OK && !Reply.Found,"no Data return before every physical tail");
    testRequire(xcronServiceClose(F.Service,false,NULL) && xcronServiceClose(F.Service,true,NULL) && xcronServiceWaitFor(F.Service,0,NULL)==XWAIT_TIMEOUT,"selected close remains asynchronous through body tails");xcronserviceissue I;testRequire(!xcronServiceDestroy(F.Service,&I) && I.Code==XCRON_SERVICE_BUSY,"busy selected destroy preserves Data and completion duties");xrtClearError();xrtAtomic32Store(&F.Gate,1,XMEMORY_RELEASE);testRequire(xcronServiceWaitFor(F.Service,10000,NULL)==XWAIT_OK,"selected tails physically returned");
    xcronselectedretired R;bool Found;testRequire(xcronServiceReapStoppedSelected(F.Service,&R,&Found,NULL) && Found && R.Id==Job && R.Data==Data && R.Info.Cancelled==2,"selected retirement returns heap Data after both tails");xrtFree(Data);
    for(unsigned N=0;N<2;++N){xcronselectedservicecompletion D=ssDone(F.Service);testRequire(D.Completion.Result==XCRON_RUN_CANCELLED && !D.Completion.Error && D.Candidates==2 && !memcmp(&D.Local,&Local,sizeof(Local)),"ready copied nominal records survive Data free");}ssClear(&F);ssPoolEnd(E);

    ssFoldFixture(&Z,At,&Local);F=ssFixture(At[1],&Local,2);E=ssPool(2,8);C=ssConfig(E,&F);C.Service.BatchLimit=C.Service.CompletionLimit=1;C.Service.Scheduler.WorkLimit=1;ssStart(&F,&C);J=ssJob(Z,&F,At[0],At[1]);Job=ssAdd(&F,&J,(xcrondeliverypolicy){0,1});xcronZoneRelease(Z);ssReady(&F,1,0);xrtSleep(15);xcronselectedservicestats T=ssStats(F.Service);testRequire(T.Service.Kernel.Dispatched==1 && T.Service.ReservedCompletions==1 && xrtAtomic64Load(&F.Calls,XMEMORY_ACQUIRE)==1,"full selected metadata output prevents another lease");
    xcronselectedservicecompletion D=ssDone(F.Service);testRequire(D.Completion.ScheduledAt==At[0] && D.Candidates==2,"first bounded selected output");D=ssDone(F.Service);testRequire(D.Completion.ScheduledAt==At[1] && D.Candidates==2,"released metadata credit admits remaining selected fold");ssStop(&F);ssClear(&F);ssPoolEnd(E);
}
